@@ renderAndStoreSiteComponent, immediately before the RenderTemplate call (~:529)
+	// Schema-driven fill. renderCtx.ContentData (built at :222-262) is a FIXED
+	// vocabulary; a component declaring any other field name previously got ""
+	// for it, silently (component_library.go:552 blanks Go's <no value>), and an
+	// ungated template turned that into href="". Resolve what the component
+	// actually declares, reusing the page-section resolver (same package).
+	if len(inputSchemaRaw) > 0 {
+		var schema struct {
+			Fields map[string]map[string]interface{} `json:"fields"`
+		}
+		if err := json.Unmarshal(inputSchemaRaw, &schema); err != nil {
+			// Malformed schema must never break a site that renders fine today.
+			logger.Warn("site chrome: input_schema unparseable; rendering with fixed vocabulary only",
+				zap.String("slot", slot), zap.Error(err))
+		} else {
+			resolver := newSourceResolver(siteID, db, logger, "") // site-wide: no page
+			var unresolved []string
+			for name, def := range schema.Fields {
+				// (a) GAP-FILL ONLY — never override the fixed vocabulary.
+				// Keeps LNK-007's resolved cta_url / legal links authoritative.
+				if existing, ok := renderCtx.ContentData[name]; ok {
+					s, isStr := existing.(string)
+					if !isStr || s != "" {
+						continue
+					}
+				}
+				source, _ := def["source"].(string)
+
+				// (b) static: the declared literal IS the value (e.g. site-header
+				// nav_aria_label fallback "Main navigation", which chrome has never
+				// applied). Mirrors plan_sections_action.go:1210-1218.
+				if source == "" || source == "static" || strings.HasPrefix(source, "static.") {
+					if fb := def["fallback"]; fb != nil {
+						renderCtx.ContentData[name] = fb
+					} else {
+						unresolved = append(unresolved, name)
+					}
+					continue
+				}
+				// llm/renderer fields are not ours to resolve here.
+				if source == "llm" || source == "renderer" || strings.HasPrefix(source, "renderer.") {
+					unresolved = append(unresolved, name)
+					continue
+				}
+				if v, found := resolver.resolve(ctx, source); found && v != nil {
+					renderCtx.ContentData[name] = v
+					logger.Info("site chrome: schema field resolved",
+						zap.String("slot", slot), zap.String("field", name),
+						zap.String("source", source))
+					continue
+				}
+				// MISSED. Do NOT apply def["fallback"] — header-bold-gradient's
+				// cta_url fallback is /contact.html, the fossil of the phantom-CTA
+				// bug LNK-007 fixed. Correct-or-absent (LNK-005): leave it unset and
+				// let the template gate it.
+				unresolved = append(unresolved, name)
+			}
+			/* edit 3 reports `unresolved` */
+		}
+	}
 	renderedHTML := RenderTemplate(htmlTemplate, renderCtx, logger)
